"""Encrypted session store: persistent auth artifacts encrypted with a libsodium secret box,
the master key held in the GNOME login keyring (Secret Service), or a 0600 key file if absent."""

import base64
import binascii
import json
import logging
import os

import nacl.exceptions
import nacl.secret
import nacl.utils

from .. import paths
from ..errors import AppleError

logger = logging.getLogger(__name__)

_ATTRS = {"application": "icp", "type": "master-key"}
_LABEL = "ApplePasswords-Linux master key"
_KEY_SIZE = nacl.secret.SecretBox.KEY_SIZE


class SessionError(AppleError):
    """The stored session exists but cannot be read with the current master key."""


def _decode_key(stored: bytes | str | None) -> bytes | None:
    if stored is None:
        return None
    raw = stored.encode() if isinstance(stored, str) else bytes(stored)
    if len(raw) == _KEY_SIZE:
        return raw
    try:
        key = base64.b64decode(raw.strip(), validate=True)
    except (binascii.Error, ValueError):
        return None
    return key if len(key) == _KEY_SIZE else None


def _key_from_secret_service() -> bytes | None:
    try:
        import secretstorage
    except Exception:
        return None
    try:
        conn = secretstorage.dbus_init()
        coll = secretstorage.get_default_collection(conn)
        if coll.is_locked() and coll.unlock():
            logger.warning("keyring unlock dismissed; using key file fallback")
            return None
        unusable = 0
        for item in coll.search_items(_ATTRS):
            key = _decode_key(item.get_secret())
            if key is not None:
                return key
            unusable += 1
        if unusable:
            logger.warning("keyring holds %d unusable master-key item(s); replacing them", unusable)
        key = nacl.utils.random(_KEY_SIZE)
        coll.create_item(_LABEL, _ATTRS, base64.b64encode(key), replace=True)
        return key
    except Exception as e:  # dbus not running, no keyring, etc.
        logger.warning("Secret Service unavailable (%s); using key file fallback", e)
        return None


def _key_from_file() -> bytes:
    f = paths.fallback_key_file()
    if f.exists():
        key = _decode_key(f.read_bytes())
        if key is not None:
            return key
        logger.warning("master key file %s is unusable; writing a fresh key", f)
    key = nacl.utils.random(_KEY_SIZE)
    _write_private(f, base64.b64encode(key))
    logger.warning("Stored master key at %s (0600) - less safe than the keyring", f)
    return key


def _master_key() -> bytes:
    key = _key_from_secret_service()
    return key if key is not None else _key_from_file()


def _write_private(f, data: bytes) -> None:
    """Write 0600 from creation - secrets must never exist world-readable, even briefly."""
    fd = os.open(f, os.O_WRONLY | os.O_CREAT | os.O_TRUNC, 0o600)
    with os.fdopen(fd, "wb") as fh:
        fh.write(data)
    os.chmod(f, 0o600)


def save(data: dict) -> None:
    box = nacl.secret.SecretBox(_master_key())
    _write_private(paths.session_file(), box.encrypt(json.dumps(data).encode()))


def load() -> dict | None:
    f = paths.session_file()
    if not f.exists():
        return None
    box = nacl.secret.SecretBox(_master_key())
    try:
        return json.loads(box.decrypt(f.read_bytes()).decode())
    except nacl.exceptions.CryptoError as e:
        raise SessionError(
            f"cannot decrypt {f} - the master key no longer matches it (the keyring entry was "
            "lost or replaced). Run `icp logout`, then `icp login` to sign in again.") from e


def clear() -> None:
    f = paths.session_file()
    if f.exists():
        f.unlink()

"""Terminal output and prompt helpers. Normal output goes to stdout; progress/warnings/errors
go to stderr so `icp ... > file` captures only the result."""
import getpass
import sys


def out(msg: str = "") -> None:
    print(msg)


def step(msg: str) -> None:
    print(msg, file=sys.stderr)


def warn(msg: str) -> None:
    print(f"warning: {msg}", file=sys.stderr)


def err(msg: str) -> None:
    print(f"error: {msg}", file=sys.stderr)


def ask(msg: str) -> str:
    return input(msg).strip()


def secret(msg: str) -> str:
    return getpass.getpass(msg)


def confirm_yn(msg: str) -> bool:
    """Yes/No prompt that defaults to No (empty or anything but y/yes)."""
    return input(msg).strip().lower() in ("y", "yes")

"""Diagnostic logging for the token flow. `login --debug` writes a redacted transcript to
~/.config/icp/debug-<ts>.log - secret values are replaced with their length, safe to share."""

import json
import logging
import time
from pathlib import Path

from . import paths

# Keys whose string values must never be written verbatim.
_SECRET_HINTS = (
    "token", "pet", "sk", "spd", "m1", "m2", "secret", "password", "pwd",
    "cookie", "auth", "prk", "et", "key", "salt", "challenge",
)


def redact(value, key: str = ""):
    if isinstance(value, (bytes, bytearray)):
        return f"<bytes:{len(value)}>"
    if isinstance(value, dict):
        return {k: redact(v, str(k)) for k, v in value.items()}
    if isinstance(value, (list, tuple)):
        return [redact(v, key) for v in value]
    if isinstance(value, str):
        low = key.lower()
        if any(h in low for h in _SECRET_HINTS) and len(value) > 8:
            return f"<redacted:{len(value)}>"
        if len(value) > 80:
            return f"<str:{len(value)}>"
        return value
    return value


def start() -> Path:
    """Attach a DEBUG file handler; return the log path."""
    path = paths.config_dir() / f"debug-{int(time.time())}.log"
    handler = logging.FileHandler(path)
    handler.setLevel(logging.DEBUG)
    handler.setFormatter(logging.Formatter("%(asctime)s %(levelname)s %(name)s: %(message)s"))
    logger = logging.getLogger("icp")
    logger.setLevel(logging.DEBUG)
    logger.addHandler(handler)
    path.chmod(0o600)
    return path


def dump(logger: logging.Logger, label: str, obj) -> None:
    logger.debug("%s (redacted):\n%s", label, json.dumps(redact(obj), indent=2, default=str))


def dump_token_dict(logger: logging.Logger, spd: dict) -> None:
    """Log the available app tokens by name + expiry - the most useful single artifact."""
    t = spd.get("t") or {}
    logger.debug("spd contains %d app token(s):", len(t))
    for name, entry in t.items():
        if isinstance(entry, dict):
            logger.debug("  token %r -> fields=%s expiry=%s",
                         name, list(entry.keys()), entry.get("expiry"))
        else:
            logger.debug("  token %r -> %s", name, type(entry).__name__)
    logger.debug("spd top-level keys: %s", list(spd.keys()))
    logger.debug("ids present: adsid=%s DsPrsId=%s GsIdmsToken=%s",
                 bool(spd.get("adsid")), bool(spd.get("DsPrsId")), bool(spd.get("GsIdmsToken")))

"""Common base for the package's Apple-protocol exceptions."""


class AppleError(RuntimeError):
    """Base for every error raised against an Apple service or its wire formats."""

"""Hide My Email (iCloud+ alias) client - a thin read-only JSON REST layer authed purely by
the web session's cookies. See RESEARCH.md "Hide My Email"."""

from __future__ import annotations

import dataclasses

import requests

from ..errors import AppleError


class HmeError(AppleError):
    pass


# Origin/Referer of the icloud.com page that normally makes this XHR call.
_HEADERS = {"Accept": "application/json", "Origin": "https://www.icloud.com",
           "Referer": "https://www.icloud.com/"}


def _error_detail(data: dict) -> str:
    """Apple's `error` field shape varies (dict, bare int, or absent); fall back to the raw body."""
    err = data.get("error")
    if isinstance(err, dict):
        return err.get("errorMessage") or err.get("message") or str(err)
    if err is not None:
        return str(err)
    return data.get("errorMessage") or data.get("message") or str(data)


@dataclasses.dataclass(frozen=True)
class HmeAlias:
    anonymous_id: str
    address: str
    label: str
    note: str
    forward_to: str
    is_active: bool
    domain: str
    created_at: float  # unix epoch seconds

    def public_dict(self) -> dict:
        return {"address": self.address, "label": self.label, "domain": self.domain}


class HmeClient:
    def __init__(self, base_url: str, http: requests.Session):
        self._v2 = base_url.rstrip("/") + "/v2"
        self.http = http

    def list(self) -> list[HmeAlias]:
        resp = self.http.get(f"{self._v2}/hme/list", headers=_HEADERS, timeout=20)
        try:
            data = resp.json()
        except ValueError as e:
            raise HmeError(f"non-JSON response from hme/list (HTTP {resp.status_code})") from e
        if not resp.ok or not data.get("success"):
            raise HmeError(f"hme/list failed (HTTP {resp.status_code}): {_error_detail(data)}")
        result = data.get("result") or {}
        return [_parse(e) for e in result.get("hmeEmails", [])]


def _parse(e: dict) -> HmeAlias:
    return HmeAlias(
        anonymous_id=e.get("anonymousId", ""),
        address=e.get("hme", ""),
        label=e.get("label", ""),
        note=e.get("note", ""),
        forward_to=e.get("forwardToEmail", ""),
        is_active=bool(e.get("isActive")),
        domain=e.get("domain", ""),
        created_at=(e.get("createTimestamp") or 0) / 1000,
    )

"""iCloud Keychain decryption: SF-ECIES (P-384 / X9.63-KDF / AES-256-GCM) and AES-256-SIV
key unwrap. See RESEARCH.md "keychain/crypto.py"."""

from __future__ import annotations

import hashlib

from cryptography.hazmat.primitives.asymmetric import ec
from cryptography.hazmat.primitives.ciphers.aead import AESGCM, AESSIV

from ..errors import AppleError


class KeychainCryptoError(AppleError):
    pass


def x963_kdf(secret: bytes, shared_info: bytes, length: int,
             hashfn=hashlib.sha256) -> bytes:
    out = bytearray()
    counter = 1
    while len(out) < length:
        out += hashfn(secret + counter.to_bytes(4, "big") + shared_info).digest()
        counter += 1
    return bytes(out[:length])


def ecies_decrypt(private_key: ec.EllipticCurvePrivateKey, ephemeral_sender_pub: bytes,
                  ciphertext: bytes, auth_code: bytes) -> bytes:
    eph_pub = ec.EllipticCurvePublicKey.from_encoded_point(
        private_key.curve, ephemeral_sender_pub)
    secret = private_key.exchange(ec.ECDH(), eph_pub)
    derived = x963_kdf(secret, ephemeral_sender_pub, 48)
    key, iv = derived[:32], derived[32:48]
    return AESGCM(key).decrypt(iv, ciphertext + auth_code, None)


def ecies_decrypt_sf(private_key: ec.EllipticCurvePrivateKey, ies: dict) -> bytes:
    """Decrypt an Apple `IESCiphertext` dict (unarchived from a TLKShare `wrappedkey`)."""
    eph = bytes(ies["SFEphemeralSenderPublicKeyExternaRepresentation"])
    ct = bytes(ies["SFCiphertext"])
    tag = bytes(ies["SFIESAuthenticationCode"])
    # SecurityFoundation appends 97+16 bytes of junk to the stored ciphertext; trim it.
    real_ct = ct[:-(97 + 16)] if len(ct) > 97 + 16 else ct
    return ecies_decrypt(private_key, eph, real_ct, tag)


def siv_unwrap(key64: bytes, wrapped: bytes, associated_data=None) -> bytes:
    return AESSIV(key64).decrypt(wrapped, list(associated_data or []))


def _strip_iso7816_padding(data: bytes) -> bytes:
    ptr = len(data)
    while ptr > 0:
        ptr -= 1
        if data[ptr] == 0x00:
            continue
        if data[ptr] == 0x80:
            return data[:ptr]
        raise KeychainCryptoError("bad ISO-7816-4 padding")
    return data


def decrypt_item(item_key64: bytes, data: bytes, aad_values=None) -> bytes:
    """Decrypt an `item` record's `data` (= randomIV(16) || SIV(tag||ciphertext)). The leading
    random IV is prepended as the first associated-data element."""
    iv = data[:16]
    headers = [iv] + list(aad_values or [])
    plaintext = siv_unwrap(item_key64, data[16:], headers)
    return _strip_iso7816_padding(plaintext)

"""Minimal NSKeyedArchiver expander: resolve the `plistlib.UID` object graph Apple uses for
the per-TLKShare `IESCiphertext` into plain Python."""

from __future__ import annotations

import plistlib


def expand(data: bytes):
    """Expand an NSKeyedArchiver bplist into plain Python (dicts/lists/bytes/str/None)."""
    plist = plistlib.loads(data)
    objects = plist["$objects"]

    def resolve(node):
        if isinstance(node, plistlib.UID):
            return resolve(objects[node.data])
        if node == "$null":
            return None
        if isinstance(node, dict):
            is_object = "$class" in node          # an archived NSObject (vs a plain dict)
            out = {k: resolve(v) for k, v in node.items() if not k.startswith("$")}
            # Unwrap the common Foundation container objects to their payload, so e.g. an
            # NSData/NSMutableData value (the IESCiphertext ephemeral key) yields raw bytes,
            # not {"NS.data": ...}.
            if is_object:
                if "NS.data" in out:
                    return out["NS.data"]
                if "NS.string" in out:
                    return out["NS.string"]
                if "NS.objects" in out:
                    return out["NS.objects"]
            return out
        if isinstance(node, list):
            return [resolve(v) for v in node]
        return node

    top = plist["$top"]
    if isinstance(top, dict) and "root" in top:
        return resolve(top["root"])
    return resolve(top)

"""Octagon peer key material - two P-384 key pairs (signing + encryption) and the peerID
derived from a signed permanentInfo. Pure offline crypto, no network calls.

See RESEARCH.md "octagon/keys.py" for the byte-exact format pins (X9.63/SPKI encodings,
TPPBPeerPermanentInfo fields, ECDSA domain separation, peerID hash).
"""

from __future__ import annotations

import base64
import dataclasses
import hashlib
import time

from cryptography.hazmat.primitives import hashes, serialization
from cryptography.hazmat.primitives.asymmetric import ec

_TPHASH = {
    "SHA256": hashlib.sha256,
    "SHA384": hashlib.sha384,
}

_CURVE = ec.SECP384R1()
_COORD = 48
_POINT_LEN = 1 + 2 * _COORD          # 0x04 || X || Y      = 97


@dataclasses.dataclass
class PeerKey:
    """One P-384 key pair (a peer has two: signing + encryption)."""

    private_key: ec.EllipticCurvePrivateKey

    def public_x963(self) -> bytes:
        """`0x04 || X || Y` (97 bytes) - SecKey external rep of the public key."""
        return self.private_key.public_key().public_bytes(
            serialization.Encoding.X962,
            serialization.PublicFormat.UncompressedPoint,
        )

    def public_spki(self) -> bytes:
        """SubjectPublicKeyInfo DER - the standard X.509 public-key wrapper."""
        return self.private_key.public_key().public_bytes(
            serialization.Encoding.DER,
            serialization.PublicFormat.SubjectPublicKeyInfo,
        )

    def private_x963(self) -> bytes:
        """`0x04 || X || Y || D` (145 bytes) - SecKeyCopyExternalRepresentation
        of a full EC key, i.e. the bytes Octagon stores as OTPrivateKey.keyData."""
        d = self.private_key.private_numbers().private_value
        return self.public_x963() + d.to_bytes(_COORD, "big")

    def sign_sha384(self, data: bytes) -> bytes:
        return self.private_key.sign(data, ec.ECDSA(hashes.SHA384()))


def generate_peer_key() -> PeerKey:
    return PeerKey(ec.generate_private_key(_CURVE))


def load_peer_key_x963(blob: bytes) -> PeerKey:
    """Inverse of `PeerKey.private_x963` - reconstruct a key from stored OTPrivateKey bytes."""
    d = int.from_bytes(blob[_POINT_LEN:], "big")
    return PeerKey(ec.derive_private_key(d, _CURVE))


@dataclasses.dataclass
class PeerKeySet:
    """The two key pairs that make up one Octagon self-peer identity."""

    signing: PeerKey
    encryption: PeerKey

    @classmethod
    def generate(cls) -> "PeerKeySet":
        return cls(signing=generate_peer_key(), encryption=generate_peer_key())

    def to_storage(self) -> dict:
        """Serializable form for the encrypted session store (hex of the X9.63 privates)."""
        return {
            "curve": "P-384",
            "signing_priv_x963": self.signing.private_x963().hex(),
            "encryption_priv_x963": self.encryption.private_x963().hex(),
        }

    @classmethod
    def from_storage(cls, d: dict) -> "PeerKeySet":
        return cls(
            signing=load_peer_key_x963(bytes.fromhex(d["signing_priv_x963"])),
            encryption=load_peer_key_x963(bytes.fromhex(d["encryption_priv_x963"])),
        )


def tphash(data: bytes, algo: str = "SHA256") -> str:
    """TPHashBuilder: `"<ALGO>:" + base64(digest)`. Used for peerIDs, policy-doc and
    preapproval hashes throughout Octagon."""
    return f"{algo}:" + base64.b64encode(_TPHASH[algo](data).digest()).decode()


def derive_peer_id(permanent_info_data: bytes, sig: bytes, algo: str = "SHA256") -> str:
    """peerID = tphash(data ++ sig) - hashes the concatenation, not data alone. The randomized
    ECDSA sig makes peerID generated-once; verifiers only re-check peerID == hash(data||sig)."""
    return tphash(permanent_info_data + sig, algo)


PERMANENT_INFO_SIG_TYPE = "TPPB.PeerPermanentInfo"

_F_EPOCH, _F_SIGNING, _F_ENCRYPTION, _F_MACHINE, _F_MODEL, _F_CREATION = 1, 2, 3, 4, 5, 6
_WT_VARINT, _WT_LEN = 0, 2


def _pb_varint(v: int) -> bytes:
    out = bytearray()
    while True:
        b = v & 0x7F
        v >>= 7
        out.append(b | (0x80 if v else 0))
        if not v:
            return bytes(out)


def _pb_tag(field: int, wire: int) -> bytes:
    return _pb_varint((field << 3) | wire)


def _pb_uint64(field: int, value: int) -> bytes:
    return _pb_tag(field, _WT_VARINT) + _pb_varint(value)


def _pb_len(field: int, data: bytes) -> bytes:
    return _pb_tag(field, _WT_LEN) + _pb_varint(len(data)) + data


def _pb_read_varint(data: bytes, pos: int) -> tuple[int, int]:
    shift, val = 0, 0
    while True:
        b = data[pos]
        pos += 1
        val |= (b & 0x7F) << shift
        if not (b & 0x80):
            return val, pos
        shift += 7


def munge_model_id(model_id: str) -> str:
    """`+[TPPeerPermanentInfo mungeModelID:]` - pass-through on production builds."""
    return model_id


def serialize_permanent_info_data(signing_spki: bytes, encryption_spki: bytes,
                                  machine_id: str, model_id: str, epoch: int,
                                  creation_time: int) -> bytes:
    return b"".join([
        _pb_uint64(_F_EPOCH, epoch),
        _pb_len(_F_SIGNING, signing_spki),
        _pb_len(_F_ENCRYPTION, encryption_spki),
        _pb_len(_F_MACHINE, machine_id.encode("utf-8")),
        _pb_len(_F_MODEL, munge_model_id(model_id).encode("utf-8")),
        _pb_uint64(_F_CREATION, creation_time),
    ])


def _prefixed_data(data: bytes, sig_type: str) -> bytes:
    """`prefixedData()` - UTF8(sigTypeName) ++ data (domain separation for typesafe sigs)."""
    return sig_type.encode("utf-8") + data


@dataclasses.dataclass
class PermanentInfo:
    peer_id: str
    data: bytes          # the TPPBPeerPermanentInfo proto bytes
    sig: bytes           # ECDSA-P384-SHA384 over prefixedData(data, TPPB.PeerPermanentInfo)
    machine_id: str
    model_id: str
    epoch: int
    creation_time: int

    def to_storage(self) -> dict:
        return {
            "peer_id": self.peer_id,
            "data": self.data.hex(),
            "sig": self.sig.hex(),
            "machine_id": self.machine_id,
            "model_id": self.model_id,
            "epoch": self.epoch,
            "creation_time": self.creation_time,
        }


def build_permanent_info(keys: PeerKeySet, machine_id: str, model_id: str,
                         epoch: int = 1, creation_time: int | None = None) -> PermanentInfo:
    """Build the signed self-peer permanentInfo and derive its peerID."""
    if creation_time is None:
        creation_time = int(time.time())
    signing_spki = keys.signing.public_spki()
    encryption_spki = keys.encryption.public_spki()
    data = serialize_permanent_info_data(signing_spki, encryption_spki,
                                         machine_id, model_id, epoch, creation_time)
    sig = keys.signing.sign_sha384(_prefixed_data(data, PERMANENT_INFO_SIG_TYPE))
    peer_id = derive_peer_id(data, sig)
    return PermanentInfo(peer_id=peer_id, data=data, sig=sig, machine_id=machine_id,
                         model_id=munge_model_id(model_id), epoch=epoch,
                         creation_time=creation_time)


STABLE_INFO_SIG_TYPE = "TPPB.PeerStableInfo"

UCV_FOLLOWING = 1  # UserControllableViewStatus enum value

_S_CLOCK, _S_FROZEN_VERSION, _S_FROZEN_HASH = 1, 2, 3
_S_OSVERSION, _S_DEVICENAME, _S_SERIAL = 5, 6, 9
_S_FLEX_VERSION, _S_FLEX_HASH, _S_UCV = 10, 11, 12
_S_REPUDIATION = 19


def _pb_bool(field: int, value: bool) -> bytes:
    return _pb_uint64(field, 1 if value else 0)


def serialize_stable_info_data(clock: int, frozen_policy_version: int, frozen_policy_hash: str,
                               flexible_policy_version: int, flexible_policy_hash: str,
                               device_name: str, serial_number: str, os_version: str,
                               user_controllable_views: int = UCV_FOLLOWING,
                               supports_repudiation: bool = True) -> bytes:
    return b"".join([
        _pb_uint64(_S_CLOCK, clock),
        _pb_uint64(_S_FROZEN_VERSION, frozen_policy_version),
        _pb_len(_S_FROZEN_HASH, frozen_policy_hash.encode("utf-8")),
        _pb_len(_S_OSVERSION, os_version.encode("utf-8")),
        _pb_len(_S_DEVICENAME, device_name.encode("utf-8")),
        _pb_len(_S_SERIAL, serial_number.encode("utf-8")),
        _pb_uint64(_S_FLEX_VERSION, flexible_policy_version),
        _pb_len(_S_FLEX_HASH, flexible_policy_hash.encode("utf-8")),
        _pb_uint64(_S_UCV, user_controllable_views),
    ] + ([_pb_bool(_S_REPUDIATION, True)] if supports_repudiation else []))


@dataclasses.dataclass
class StableInfo:
    data: bytes          # TPPBPeerStableInfo proto bytes
    sig: bytes           # ECDSA-P384-SHA384 over prefixedData(data, "TPPB.PeerStableInfo")
    clock: int
    frozen_policy_version: int
    flexible_policy_version: int

    def to_storage(self) -> dict:
        return {"data": self.data.hex(), "sig": self.sig.hex(), "clock": self.clock,
                "frozen_policy_version": self.frozen_policy_version,
                "flexible_policy_version": self.flexible_policy_version}


def build_stable_info(keys: PeerKeySet, clock: int, frozen_policy_version: int,
                      frozen_policy_hash: str, flexible_policy_version: int,
                      flexible_policy_hash: str, device_name: str, serial_number: str,
                      os_version: str, user_controllable_views: int = UCV_FOLLOWING,
                      supports_repudiation: bool = True) -> StableInfo:
    """Build and sign the peer's stableInfo (attached to the permanentInfo's peerID)."""
    data = serialize_stable_info_data(
        clock, frozen_policy_version, frozen_policy_hash, flexible_policy_version,
        flexible_policy_hash, device_name, serial_number, os_version,
        user_controllable_views, supports_repudiation)
    sig = keys.signing.sign_sha384(_prefixed_data(data, STABLE_INFO_SIG_TYPE))
    return StableInfo(data=data, sig=sig, clock=clock,
                      frozen_policy_version=frozen_policy_version,
                      flexible_policy_version=flexible_policy_version)


def parse_stable_info_data(data: bytes) -> dict:
    pos, out, n = 0, {}, len(data)
    names_varint = {_S_CLOCK: "clock", _S_FROZEN_VERSION: "frozen_policy_version",
                    _S_FLEX_VERSION: "flexible_policy_version", _S_UCV: "user_controllable_views",
                    _S_REPUDIATION: "supports_repudiation"}
    names_str = {_S_FROZEN_HASH: "frozen_policy_hash", _S_OSVERSION: "os_version",
                 _S_DEVICENAME: "device_name", _S_SERIAL: "serial_number",
                 _S_FLEX_HASH: "flexible_policy_hash"}
    while pos < n:
        tag, pos = _pb_read_varint(data, pos)
        field, wire = tag >> 3, tag & 7
        if wire == _WT_VARINT:
            val, pos = _pb_read_varint(data, pos)
            if field in names_varint:
                out[names_varint[field]] = val
        elif wire == _WT_LEN:
            ln, pos = _pb_read_varint(data, pos)
            chunk = data[pos:pos + ln]
            pos += ln
            if field in names_str:
                out[names_str[field]] = chunk.decode("utf-8")
    return out


VOUCHER_SIG_TYPE = "TPPB.Voucher"
DYNAMIC_INFO_SIG_TYPE = "TPPB.PeerDynamicInfo"
_D_CLOCK, _D_INCLUDED, _D_EXCLUDED, _D_PREAPPROVALS = 1, 2, 3, 5


def serialize_dynamic_info_data(clock: int, included_peer_ids: list[str],
                                excluded_peer_ids: list[str] | None = None,
                                preapprovals: list[str] | None = None) -> bytes:
    """TPPBPeerDynamicInfo proto - the mutable trust graph (self + existing trusted peers)."""
    parts = [_pb_uint64(_D_CLOCK, clock)]
    for pid in included_peer_ids:
        parts.append(_pb_len(_D_INCLUDED, pid.encode("utf-8")))
    for pid in (excluded_peer_ids or []):
        parts.append(_pb_len(_D_EXCLUDED, pid.encode("utf-8")))
    for h in (preapprovals or []):
        parts.append(_pb_len(_D_PREAPPROVALS, h.encode("utf-8")))
    return b"".join(parts)


@dataclasses.dataclass
class DynamicInfo:
    data: bytes
    sig: bytes
    clock: int
    included_peer_ids: list[str]

    def to_storage(self) -> dict:
        return {"data": self.data.hex(), "sig": self.sig.hex(), "clock": self.clock,
                "included_peer_ids": list(self.included_peer_ids)}


def build_dynamic_info(keys: PeerKeySet, clock: int, included_peer_ids: list[str],
                       excluded_peer_ids: list[str] | None = None,
                       preapprovals: list[str] | None = None) -> DynamicInfo:
    """Build and sign the peer's dynamicInfo."""
    data = serialize_dynamic_info_data(clock, included_peer_ids, excluded_peer_ids, preapprovals)
    sig = keys.signing.sign_sha384(_prefixed_data(data, DYNAMIC_INFO_SIG_TYPE))
    return DynamicInfo(data=data, sig=sig, clock=clock,
                       included_peer_ids=list(included_peer_ids))


def parse_dynamic_info_data(data: bytes) -> dict:
    pos, n = 0, len(data)
    out: dict = {"included": [], "excluded": [], "preapprovals": []}
    while pos < n:
        tag, pos = _pb_read_varint(data, pos)
        field, wire = tag >> 3, tag & 7
        if wire == _WT_VARINT:
            val, pos = _pb_read_varint(data, pos)
            if field == _D_CLOCK:
                out["clock"] = val
        elif wire == _WT_LEN:
            ln, pos = _pb_read_varint(data, pos)
            chunk = data[pos:pos + ln]
            pos += ln
            if field == _D_INCLUDED:
                out["included"].append(chunk.decode("utf-8"))
            elif field == _D_EXCLUDED:
                out["excluded"].append(chunk.decode("utf-8"))
            elif field == _D_PREAPPROVALS:
                out["preapprovals"].append(chunk.decode("utf-8"))
    return out

