"""Minimal protobuf wire codec - enough to build/parse the Cuttlefish + CloudKit messages,
hand-rolled to keep byte-exact control over field ordering (Apple signs some of these blobs)."""

from __future__ import annotations

WT_VARINT = 0
WT_LEN = 2
WT_I64 = 1
WT_I32 = 5


class ProtoError(ValueError):
    pass


def encode_varint(v: int) -> bytes:
    if v < 0:
        v &= (1 << 64) - 1  # two's complement for negative ints (proto int64)
    out = bytearray()
    while True:
        b = v & 0x7F
        v >>= 7
        out.append(b | (0x80 if v else 0))
        if not v:
            return bytes(out)


def _tag(field: int, wire: int) -> bytes:
    return encode_varint((field << 3) | wire)


class Writer:
    """Accumulates fields in call order. Call fields in ascending field-number order when the
    output is going to be signed (matches Apple's generated `writeTo:` canonical ordering)."""

    def __init__(self) -> None:
        self._buf = bytearray()

    def uint64(self, field: int, value: int | None) -> "Writer":
        if value is not None:
            self._buf += _tag(field, WT_VARINT) + encode_varint(value)
        return self

    def bool(self, field: int, value: bool | None) -> "Writer":
        if value is not None:
            self._buf += _tag(field, WT_VARINT) + encode_varint(1 if value else 0)
        return self

    def bytes(self, field: int, value: bytes | None) -> "Writer":
        if value is not None:
            self._buf += _tag(field, WT_LEN) + encode_varint(len(value)) + value
        return self

    def string(self, field: int, value: str | None) -> "Writer":
        if value is not None:
            return self.bytes(field, value.encode("utf-8"))
        return self

    def message(self, field: int, value: "Writer | bytes | None") -> "Writer":
        if value is None:
            return self
        raw = value.finish() if isinstance(value, Writer) else value
        return self.bytes(field, raw)

    def finish(self) -> bytes:
        return bytes(self._buf)


def decode_fields(data: bytes) -> dict:
    """Parse raw wire data into {field_number: [values...]}, preserving repeats.

    Values are: int for varint/i32/i64, bytes for length-delimited. Callers interpret bytes as
    string/sub-message as needed. Unknown fields are kept (so round-trips don't silently drop).
    """
    pos, n = 0, len(data)
    out: dict[int, list] = {}

    def read_varint(p):
        shift, val = 0, 0
        while True:
            if p >= n:
                raise ProtoError("truncated varint")
            b = data[p]
            p += 1
            val |= (b & 0x7F) << shift
            if not (b & 0x80):
                return val, p
            shift += 7

    while pos < n:
        tag, pos = read_varint(pos)
        field, wire = tag >> 3, tag & 7
        if wire == WT_VARINT:
            val, pos = read_varint(pos)
        elif wire == WT_LEN:
            ln, pos = read_varint(pos)
            val = data[pos:pos + ln]
            pos += ln
            if len(val) != ln:
                raise ProtoError("truncated length-delimited field")
        elif wire == WT_I64:
            val = int.from_bytes(data[pos:pos + 8], "little")
            pos += 8
        elif wire == WT_I32:
            val = int.from_bytes(data[pos:pos + 4], "little")
            pos += 4
        else:
            raise ProtoError(f"unsupported wire type {wire} (field {field})")
        out.setdefault(field, []).append(val)
    return out


def first(fields: dict, field: int, default=None):
    vals = fields.get(field)
    return vals[0] if vals else default


def first_str(fields: dict, field: int, default=None):
    v = first(fields, field)
    return v.decode("utf-8") if isinstance(v, (bytes, bytearray)) else default

"""Cuttlefish and function-invoke wire messages for the sponsored-join path. Carries the
octagon/keys peer identity onto the wire; CloudKit container framing lives in transport/cloudkit.
See RESEARCH.md (Stages 2-4) for the field-number provenance."""

from __future__ import annotations

import dataclasses

from .codec import Writer, decode_fields, first, first_str


def encode_signed_info(info: bytes, signature: bytes) -> bytes:
    return Writer().bytes(1, info).bytes(2, signature).finish()


def parse_signed_info(raw: bytes) -> tuple[bytes, bytes]:
    f = decode_fields(raw)
    return first(f, 1, b""), first(f, 2, b"")


@dataclasses.dataclass
class SignedBlob:
    info: bytes
    sig: bytes

    def encode(self) -> bytes:
        return encode_signed_info(self.info, self.sig)


def encode_cuttlefish_peer(peer_id: str, permanent: SignedBlob, stable: SignedBlob,
                           dynamic: SignedBlob, voucher: SignedBlob | None = None) -> bytes:
    w = (Writer()
         .string(1, peer_id)
         .message(2, permanent.encode())
         .message(3, stable.encode())
         .message(4, dynamic.encode()))
    if voucher is not None:
        w.message(5, voucher.encode())
    return w.finish()


def parse_cuttlefish_peer(raw: bytes) -> dict:
    f = decode_fields(raw)
    out = {"hash": first_str(f, 1)}
    for key, num in (("permanent_info", 2), ("stable_info", 3), ("dynamic_info", 4),
                     ("voucher", 5)):
        blob = first(f, num)
        out[key] = SignedBlob(*parse_signed_info(blob)) if blob is not None else None
    return out


def encode_voucher(reason: int, beneficiary: str, sponsor: str) -> bytes:
    return Writer().uint64(1, reason).string(2, beneficiary).string(3, sponsor).finish()


@dataclasses.dataclass
class TlkShare:
    service: str = ""
    curve: int = 0
    epoch: int = 0
    key_id: str = ""
    poisoned: int = 0
    receiver: str = ""
    receiver_public_encryption_key: str = ""  # base64 SPKI
    sender: str = ""
    signature: str = ""            # base64
    version: int = 0
    wrapped_key: str = ""          # base64

    def encode(self) -> bytes:
        return (Writer()
                .string(1, self.service).uint64(2, self.curve).uint64(3, self.epoch)
                .string(4, self.key_id).uint64(5, self.poisoned).string(6, self.receiver)
                .string(7, self.receiver_public_encryption_key).string(8, self.sender)
                .string(9, self.signature).uint64(10, self.version)
                .string(11, self.wrapped_key).finish())

    @classmethod
    def parse(cls, raw: bytes) -> "TlkShare":
        f = decode_fields(raw)
        return cls(
            service=first_str(f, 1, ""), curve=first(f, 2, 0), epoch=first(f, 3, 0),
            key_id=first_str(f, 4, ""), poisoned=first(f, 5, 0), receiver=first_str(f, 6, ""),
            receiver_public_encryption_key=first_str(f, 7, ""), sender=first_str(f, 8, ""),
            signature=first_str(f, 9, ""), version=first(f, 10, 0),
            wrapped_key=first_str(f, 11, ""))


@dataclasses.dataclass
class ViewKey:
    key_id: str = ""
    top_level_key_id: str = ""
    key_number: int = 0
    key: str = ""
    hardware: str = ""

    def encode(self) -> bytes:
        return (Writer().string(1, self.key_id).string(2, self.top_level_key_id)
                .uint64(3, self.key_number).string(4, self.key).string(5, self.hardware)
                .finish())


@dataclasses.dataclass
class ViewKeys:
    service: str = ""
    top_level_key: ViewKey | None = None
    class_a: ViewKey | None = None
    class_c: ViewKey | None = None
    old_top_level_key: ViewKey | None = None

    def encode(self) -> bytes:
        w = Writer().string(1, self.service)
        for num, vk in ((2, self.top_level_key), (3, self.class_a), (4, self.class_c),
                        (5, self.old_top_level_key)):
            if vk is not None:
                w.message(num, vk.encode())
        return w.finish()


def encode_fetch_changes_request(sync_token: str | None) -> bytes:
    return Writer().string(1, sync_token).finish()


def parse_fetch_changes_response(raw: bytes) -> dict:
    f = decode_fields(raw)
    changes_blob = first(f, 1)
    if changes_blob is None:
        return {"sync_token": None, "peers": []}
    cf = decode_fields(changes_blob)
    peers = []
    for change in cf.get(2, []):
        chg = decode_fields(change)
        add = first(chg, 3)
        if add is not None:
            peers.append(parse_cuttlefish_peer(add))
    return {"sync_token": first_str(cf, 1), "peers": peers}


def encode_join_with_voucher_request(peer: bytes, shares: list[TlkShare] | None = None,
                                     keys: list[ViewKeys] | None = None,
                                     bottle: bytes | None = None,
                                     restore_point: str | None = None) -> bytes:
    """`peer` is an encoded CuttlefishPeer with its voucher SignedInfo populated by the sponsor."""
    w = (Writer().string(1, restore_point).message(2, peer).message(3, bottle))
    for s in (shares or []):
        w.message(4, s.encode())
    for k in (keys or []):
        w.message(5, k.encode())
    return w.finish()


def encode_fetch_recoverable_tlkshares_request(peer_id: str) -> bytes:
    """Asks the server for every view TLKShare our peer can recover, incl. user-controllable
    views (Passwords) that have no plain CKKS tlkshare addressed to us."""
    return Writer().string(1, peer_id).finish()


def parse_recoverable_tlkshares_response(raw: bytes) -> dict:
    """Returns the inner Record protobufs (parse with ckks.parse_record):
    {"share_records": [...], "synckey_records": [...]}."""
    f = decode_fields(raw)

    def inner(cuttlefish_record):     # CuttlefishRecord{ inner(2): Record } -> Record bytes
        return first(decode_fields(cuttlefish_record), 2) if cuttlefish_record is not None else None

    share_records, synckey_records = [], []
    for grp in f.get(1, []):
        g = decode_fields(grp)
        sh = inner(first(g, 3))
        if sh is not None:
            share_records.append(sh)
        vk = first(g, 2)
        if vk is not None:
            vf = decode_fields(vk)
            for fn in (1, 2, 3):      # tlk, classA, classB synckey records
                rec = inner(first(vf, fn))
                if rec is not None:
                    synckey_records.append(rec)
    return {"share_records": share_records, "synckey_records": synckey_records}


def encode_function_invoke_request(service: str, name: str, parameters: bytes) -> bytes:
    return Writer().string(1, service).string(2, name).bytes(3, parameters).finish()

"""One-time codes (RFC 6238) for the `totp` block iCloud Keychain stores in a login's metadata
sidecar - see RESEARCH.md. The secret stays here and in the vault; only generated codes are
handed to the browser extension."""

from __future__ import annotations

import base64
import binascii
import hashlib
import hmac
import struct
import time
import urllib.parse

_ALGORITHMS = {0: "SHA1", 1: "SHA256", 2: "SHA512"}
_HASHES = {"SHA1": hashlib.sha1, "SHA256": hashlib.sha256, "SHA512": hashlib.sha512}


def _int(value, default: int) -> int:
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def uri_from_sidecar(block) -> str:
    """An `otpauth://totp` URI for a sidecar's `totp` dict, or "" when it holds no usable secret.

    The sidecar also keeps the scanned `originalURL` verbatim, but an enrolment typed in as a
    setup key has none, so the URI is rebuilt from the structured fields instead.
    """
    if not isinstance(block, dict):
        return ""
    secret = block.get("secret")
    if not isinstance(secret, (bytes, bytearray)) or not secret:
        return ""
    issuer, account = str(block.get("issuer") or ""), str(block.get("accountName") or "")
    label = ":".join(p for p in (issuer, account) if p) or "icloud"
    params = {
        "secret": base64.b32encode(bytes(secret)).decode().rstrip("="),
        "algorithm": _ALGORITHMS.get(block.get("algorithm"), "SHA1"),
        "digits": _int(block.get("digits"), 6),
        "period": _int(block.get("period"), 30),
    }
    if issuer:
        params["issuer"] = issuer
    return f"otpauth://totp/{urllib.parse.quote(label)}?{urllib.parse.urlencode(params)}"


def generate(uri: str, at: float | None = None) -> dict:
    """-> {"code", "expires", "period"} for an `otpauth://totp` URI, or {} if it is unusable.
    `expires` is the unix second the code rolls over, so a caller can show a countdown."""
    if not uri:
        return {}
    query = urllib.parse.parse_qs(urllib.parse.urlparse(uri).query)

    def param(name, default=""):
        return (query.get(name) or [default])[0]

    raw = param("secret").replace(" ", "").upper()
    try:
        key = base64.b32decode(raw + "=" * (-len(raw) % 8))
    except binascii.Error:
        return {}
    digest = _HASHES.get(param("algorithm", "SHA1").upper())
    if not key or digest is None:
        return {}

    digits = min(max(_int(param("digits"), 6), 6), 10)
    period = max(_int(param("period"), 30), 1)
    counter = int((time.time() if at is None else at) // period)
    mac = hmac.new(key, struct.pack(">Q", counter), digest).digest()
    offset = mac[-1] & 0x0F
    code = (struct.unpack(">I", mac[offset:offset + 4])[0] & 0x7FFFFFFF) % 10 ** digits
    return {"code": f"{code:0{digits}d}", "expires": (counter + 1) * period, "period": period}

"""CKKS record fetch: pull the iCloud Keychain zone records (tlkshare / synckey / item /
currentitem) via a CloudKit RecordRetrieveChanges op per zone. See RESEARCH.md "transport/ckks.py"."""

from __future__ import annotations

import dataclasses
import struct

from ..proto.codec import Writer, decode_fields, first, first_str


@dataclasses.dataclass
class CKDate:
    """A CloudKit Date value - kept distinct from a plain double so the item AAD encodes it
    as RFC3339 rather than as a number."""
    time: float   # seconds (UNIX)


# Keychain CKKS zones (private DB). "Passwords" + "Manatee" hold web credentials.
KEYCHAIN_ZONES = (
    "Passwords", "Manatee", "Engram", "SecureObjectSync", "ProtectedCloudStorage",
    "CreditCards", "ApplePay", "WiFi", "Home", "Groups", "Contacts", "Mail",
    "LimitedPeersAllowed", "SE-PTC", "Photos",
)

ID_TYPE_RECORD_ZONE = 6
ID_TYPE_USER = 7

OP_TYPE_RECORD_RETRIEVE_CHANGES = 213
FIELD_RETRIEVE_CHANGES = 213


def _identifier(name: str, type_: int) -> bytes:
    return Writer().string(1, name).uint64(2, type_).finish()


def record_zone_identifier(zone: str, user_id: str) -> bytes:
    return (Writer()
            .message(1, _identifier(zone, ID_TYPE_RECORD_ZONE))
            .message(2, _identifier(user_id, ID_TYPE_USER))
            .finish())


def build_retrieve_changes_request(zone_identifier: bytes,
                                   continuation_token: bytes | None = None,
                                   max_changes: int = 500) -> bytes:
    return (Writer()
            .bytes(1, continuation_token)
            .message(2, zone_identifier)
            .uint64(4, max_changes)
            .finish())


@dataclasses.dataclass
class CloudKitRecord:
    record_name: str        # identifier value name (usually a UUID)
    type: str               # "item" / "synckey" / "tlkshare" / "currentitem" / ...
    fields: dict            # {field_name: python value}

    def get_bytes(self, name: str) -> bytes | None:
        v = self.fields.get(name)
        return v if isinstance(v, (bytes, bytearray)) else None

    def get_str(self, name: str) -> str | None:
        v = self.fields.get(name)
        return v if isinstance(v, str) else None


def _parse_value(raw: bytes):
    """Record.Field.Value -> python value. Types are preserved so the item AAD encodes each
    correctly: str, bytes, int, float, CKDate."""
    v = decode_fields(raw)
    if 2 in v:
        return first(v, 2)                     # bytesValue
    if 7 in v:
        return first_str(v, 7)                 # stringValue
    if 4 in v:
        return first(v, 4)                     # signedValue (int64)
    if 5 in v:                                 # doubleValue (fixed64, IEEE-754)
        return struct.unpack("<d", first(v, 5).to_bytes(8, "little"))[0]
    if 6 in v:                                 # dateValue: Date{ time(1): double }
        d = decode_fields(first(v, 6))
        if 1 in d:
            return CKDate(struct.unpack("<d", first(d, 1).to_bytes(8, "little"))[0])
    if 9 in v:                                 # referenceValue -> the target record's name,
        ref = decode_fields(first(v, 9))       # e.g. parentkeyref linking synckey->TLK / item->classkey
        rid = first(ref, 2)
        if rid is not None:
            idval = first(decode_fields(rid), 1)
            if idval is not None:
                return first_str(decode_fields(idval), 1)
    return None


def parse_record(raw: bytes) -> CloudKitRecord:
    f = decode_fields(raw)
    rec_id = first(f, 2)
    name = ""
    if rec_id is not None:
        idval = first(decode_fields(rec_id), 1)
        if idval is not None:
            name = first_str(decode_fields(idval), 1) or ""
    type_blob = first(f, 3)
    rtype = first_str(decode_fields(type_blob), 1) if type_blob is not None else ""
    fields = {}
    for fld in f.get(7, []):
        ff = decode_fields(fld)
        ident = first(ff, 1)
        fname = first_str(decode_fields(ident), 1) if ident is not None else None
        val = first(ff, 2)
        if fname is not None and val is not None:
            fields[fname] = _parse_value(val)
    return CloudKitRecord(record_name=name, type=rtype or "", fields=fields)


def parse_retrieve_changes_response(raw: bytes) -> dict:
    """Returns {records, continuation_token, status}. status 1 means another page is available;
    status 3 is the final state token for the zone."""
    f = decode_fields(raw)
    records = []
    for change in f.get(1, []):
        cf = decode_fields(change)
        rec = first(cf, 5)
        if rec is not None:
            records.append(parse_record(rec))
    return {"records": records, "continuation_token": first(f, 2), "status": first(f, 4)}

"""Native-messaging host for the browser autofill extension. Speaks Chrome's native-messaging
protocol on stdin/stdout (4-byte LE length prefix + UTF-8 JSON) and answers domain queries from
the decrypted vault, read-only.

Protocol (JSON):
  -> {"cmd":"ping"}                              <- {"ok":true,"count":N}
  -> {"cmd":"match","domain":"login.example.com"} <- {"ok":true,"credentials":[{...}]}
  -> {"cmd":"totp","domain":...,"username":...}   <- {"ok":true,"totp":{"code":...}}

A credential's one-time-code secret never crosses this protocol: `match` carries the code
generated at request time, and `totp` re-generates it when the browser's copy has rolled over.
"""

from __future__ import annotations

import dataclasses
import datetime
import json
import plistlib
import re
import struct
import sys

from .. import totp as totp_codes


@dataclasses.dataclass(frozen=True)
class Credential:
    domain: str
    username: str
    password: str
    title: str = ""
    mdat: float = 0.0
    notes: str = ""
    last_used: float = 0.0
    totp: str = ""

    @property
    def recency(self) -> float:
        return self.last_used or self.mdat

    def public_dict(self) -> dict:
        return {"domain": self.domain, "username": self.username,
                "password": self.password, "title": self.title, "mdat": self.mdat,
                "notes": self.notes, "last_used": self.last_used, "totp": self.totp}

    def wire_dict(self) -> dict:
        """The extension's view: the `totp` URI is replaced by a code generated now."""
        return {**self.public_dict(), "totp": totp_codes.generate(self.totp) or None}


_APPLE_EPOCH = 978307200  # 2001-01-01 UTC in unix seconds (Apple "absolute time" origin)


def _to_unix(value) -> float:
    """Best-effort convert a keychain date (`mdat`/`cdat`) to unix epoch seconds; 0 if unknown.
    plistlib yields a datetime for binary-plist <date>; a CKKS dateValue arrives as `CKDate`;
    a bare number is Apple absolute time (secs since 2001) when small, already-unix when large."""
    if isinstance(value, datetime.datetime):
        return value.timestamp()
    value = getattr(value, "time", value)  # ckks.CKDate -> its .time (unix seconds)
    if isinstance(value, (int, float)) and value > 0:
        return float(value) + _APPLE_EPOCH if value < 1e9 else float(value)
    return 0.0


def _normalize_host(value: str) -> str:
    """Reduce a URL or host to a bare lowercase hostname (strip scheme/port/path/leading www)."""
    v = value.strip().lower()
    if "://" in v:
        v = v.split("://", 1)[1]
    v = v.split("/", 1)[0].split("?", 1)[0]
    v = v.split("@")[-1]          # strip userinfo
    v = v.split(":", 1)[0]        # strip port
    if v.startswith("www."):
        v = v[4:]
    return v


def domains_match(page: str, stored: str) -> bool:
    """True if a stored item's domain should autofill on `page`.

    Matches exact host, and either being a sub-domain of the other (so `example.com` fills on
    `login.example.com` and vice-versa). Conservative: requires a dotted-boundary suffix so
    `notexample.com` never matches `example.com`.
    """
    p, s = _normalize_host(page), _normalize_host(stored)
    if not p or not s:
        return False
    if p == s:
        return True
    return p.endswith("." + s) or s.endswith("." + p)


def match_aliases(page_domain: str, aliases: list) -> list:
    """Hide My Email aliases (icp.hme.client.HmeAlias) whose recorded domain matches the
    page, same domains_match() rule as Credential. Duck-typed on `.domain` rather than
    importing HmeAlias - vault/ stays free of any import from the hme/ extension."""
    return [a for a in aliases if a.domain and domains_match(page_domain, a.domain)]


def _is_credential(domain: str, title: str) -> bool:
    """False for the non-login records iCloud Keychain also syncs: Protected Cloud Storage service
    blobs (label "PCS com.apple.*", whose `acct` is a base64 key) and per-site "Website Metadata"
    records. Checks the final domain/title so the marker is caught wherever it lands; real web
    logins are reverse-DNS free and never carry these names."""
    for tag in (domain, title):
        t = (tag or "").strip().lower()
        if t.startswith(("pcs ", "pcs-", "website metadata")) or "com.apple." in t:
            return False
    return True


_GENERIC_NAME_TOKENS = {
    "account", "accounts", "admin", "app", "dashboard", "login", "password", "passwords",
    "signin", "sign", "web", "www",
}


def _name_matches_host(page: str, name: str) -> bool:
    """Fallback for Passwords entries that decrypt as generic items with only a saved label.

    The iOS Passwords app can show a useful account name (for example "Cloudflare") even when
    the decrypted item has no `srvr` host. Match only whole hostname labels so this stays much
    narrower than substring matching.
    """
    labels = {label for label in _normalize_host(page).split(".") if label}
    if not labels:
        return False
    tokens = {
        token for token in re.findall(r"[a-z0-9]+", name.lower())
        if len(token) >= 4 and token not in _GENERIC_NAME_TOKENS
    }
    return bool(labels & tokens)

# `agrp` is the access group of the subsystem that wrote an item, and identifies its record type.
_AGRP_LOGIN = {"com.apple.cfnetwork", "apple"}
_AGRP_SIDECAR_PREFIX = "com.apple.password-manager"
_AGRP_CARD = "com.apple.safari.credit-cards"
_AGRP_PASSKEY = "com.apple.webkit.webauthn"

_SIDECAR_LABEL_PREFIX = "password manager metadata:"
# Allowlist: unknown keys are dropped. `s_hi` is excluded deliberately - it holds previous
# passwords in cleartext, which have no autofill use and do not belong in the vault.
_SIDECAR_KEEP = {"notes", "title", "ctxt", "totp"}
_PLUMBING_KEYSETS = ({"tlkUUID", "srcIdentity"}, {"viewName", "encryptedData"})
_CARD_KEYS = {"CardNumber", "FPANHash", "PrimaryAccountIdentifier", "CardSecurityCode"}


def _load_plist(blob: bytes):
    """Parse a binary-plist payload, or None if it isn't one."""
    if not blob.startswith(b"bplist00"):
        return None
    try:
        return plistlib.loads(blob, fmt=plistlib.FMT_BINARY)
    except Exception:  # noqa: BLE001 - a malformed payload is simply "not a plist" here
        return None


def classify_payload(value, label: str = ""):
    """Classify an item's `v_Data` -> (kind, payload).

    kind is one of:
      "password" - credential text; payload is the decoded `str`
      "sidecar"  - a metadata record; payload is its plist dict
      "card"     - a payment card; payload is its plist dict
      "plumbing" - keychain-sync internals
      "binary"   - key material

    A password is text, so a payload that is not valid UTF-8 is classified rather than decoded.
    """
    if isinstance(value, str):
        return "password", value
    if not isinstance(value, (bytes, bytearray)):
        return "password", ""
    blob = bytes(value)
    if not blob:
        return "password", ""

    parsed = _load_plist(blob)
    if parsed is not None:
        keys = set(parsed) if isinstance(parsed, dict) else set()
        if any(keyset <= keys for keyset in _PLUMBING_KEYSETS):
            return "plumbing", parsed
        if keys & _CARD_KEYS:
            return "card", parsed
        return "sidecar", parsed
    if blob.lstrip()[:5] == b"<?xml":
        return "plumbing", None
    try:
        text = blob.decode("utf-8")
    except UnicodeDecodeError:
        return "binary", None
    # Some records decode as valid UTF-8 but are not text; a password has no C0 control bytes.
    if any(ord(ch) < 0x20 and ch not in "\t\n\r" or ord(ch) == 0x7f for ch in text):
        return "binary", None
    return "password", text


def classify_item(item) -> tuple:
    """Classify a decrypted keychain item -> (kind, payload), keying on its `agrp` access group.

    Adds "passkey" and "subsystem" to the kinds `classify_payload` returns. An item whose group
    is unrecognised falls back to inspecting the payload.
    """
    agrp = str(item.get("agrp") or "")
    raw = item.get("v_Data") or item.get("password") or b""
    label = str(item.get("labl") or "")

    if agrp.startswith(_AGRP_SIDECAR_PREFIX):
        payload = classify_payload(raw, label)[1]
        return "sidecar", payload if isinstance(payload, dict) else {}
    if agrp == _AGRP_CARD:
        payload = classify_payload(raw, label)[1]
        return "card", payload if isinstance(payload, dict) else {}
    if agrp == _AGRP_PASSKEY:
        return "passkey", None
    if agrp in _AGRP_LOGIN:
        # A login group still holds the odd non-text blob.
        kind, payload = classify_payload(raw, label)
        return (kind, payload) if kind in ("password", "sidecar") else ("binary", None)
    if agrp.startswith("com.apple."):
        return "subsystem", None
    return classify_payload(raw, label)


def _sidecar_last_used(ctxt) -> float:
    """Last-used time from a sidecar's `ctxt`, keyed by browser profile:
    {"<profile>": {"lUsed": <apple-absolute-seconds>}}. Takes the most recent across profiles."""
    if not isinstance(ctxt, dict):
        return 0.0
    best = 0.0
    for per_profile in ctxt.values():
        if not isinstance(per_profile, dict):
            continue
        best = max(best, _to_unix(per_profile.get("lUsed") or per_profile.get("slUsed")))
    return best


def _sidecar_text(value) -> str:
    """A sidecar string field, which plistlib may hand back as bytes."""
    if isinstance(value, (bytes, bytearray)):
        return bytes(value).decode("utf-8", "replace")
    return str(value) if value else ""


def decode_payment_cards(items) -> list[dict]:
    """Payment-card records, decoded. Diagnostic only: `from_items` drops these, so they never
    reach the vault or the browser extension."""
    cards = []
    for it in items:
        kind, payload = classify_item(it)
        if kind == "card" and payload:
            cards.append({"id": it.get("acct") or "", **payload})
    return cards


class CredentialStore:
    """In-memory read-only store. The pipeline builds this from decrypted keychain items."""

    def __init__(self, credentials=None):
        self._creds: list[Credential] = list(credentials or [])

    def __len__(self) -> int:
        return len(self._creds)

    def all(self) -> list["Credential"]:
        return list(self._creds)

    def match(self, page_domain: str) -> list[Credential]:
        def match_rank(c: Credential) -> int | None:
            if not _is_credential(c.domain, c.title):  # filters an older, unfiltered vault too
                return None
            if domains_match(page_domain, c.domain):
                return 0 if _normalize_host(page_domain) == _normalize_host(c.domain) else 1
            stored = _normalize_host(c.domain)
            if ("." not in stored) and _name_matches_host(page_domain, c.title or c.domain):
                return 2
            return None

        ranked = [(rank, c) for c in self._creds if (rank := match_rank(c)) is not None]
        # exact-host matches first, then parent/subdomain, then label-only fallbacks; within a
        # tier, most-recently-used first, then title for a stable order.
        ranked.sort(key=lambda rc: (rc[0], -rc[1].recency, rc[1].title, rc[1].username))
        return [c for _, c in ranked]

    @classmethod
    def from_items(cls, items) -> "CredentialStore":
        """Build from decrypted keychain item dicts (plist form). Apple `inet` password items use
        `srvr` (server/domain), `acct` (username), `v_Data` (plaintext password), `labl` (title);
        tolerate the common variants.

        A login and its metadata sidecar are separate keychain items joined on `(srvr, acct)`,
        so this runs in two passes: collect both, then fold each sidecar onto its login. Cards,
        sync plumbing and key material are dropped.
        """
        logins, sidecars = [], {}
        for it in items:
            domain = (it.get("srvr") or it.get("server") or it.get("domain")
                      or it.get("url") or it.get("svce") or "")
            username = it.get("acct") or it.get("username") or it.get("user") or ""
            label = str(it.get("labl") or "")
            kind, payload = classify_item(it)
            # The label names the login the sidecar describes, so trust it over an empty payload.
            if label.lower().startswith(_SIDECAR_LABEL_PREFIX):
                kind, payload = "sidecar", payload if isinstance(payload, dict) else {}

            key = (str(domain).lower(), str(username).lower())
            if kind == "sidecar":
                if domain or username:
                    kept = {k: v for k, v in payload.items() if k in _SIDECAR_KEEP}
                    sidecars.setdefault(key, {}).update(kept)
                continue
            if kind != "password":
                continue

            title = label or str(domain)
            if not _is_credential(str(domain), title):
                continue
            # Need a host/label to match against and at least a username or password to fill.
            if (not domain and not username) or not (username or payload):
                continue
            logins.append((key, str(domain), str(username), payload, title,
                           _to_unix(it.get("mdat") or it.get("cdat"))))

        creds = []
        for key, domain, username, pw, title, mdat in logins:
            side = sidecars.get(key, {})
            title = _sidecar_text(side.get("title")) or title
            creds.append(Credential(
                domain=domain, username=username, password=pw, title=title, mdat=mdat,
                notes=_sidecar_text(side.get("notes")),
                last_used=_sidecar_last_used(side.get("ctxt")),
                totp=totp_codes.uri_from_sidecar(side.get("totp")),
            ))
        return cls(creds)


# native-messaging framing
def read_message(stream=None) -> dict | None:
    stream = stream or sys.stdin.buffer
    raw_len = stream.read(4)
    if len(raw_len) < 4:
        return None
    (length,) = struct.unpack("<I", raw_len)
    data = stream.read(length)
    if len(data) < length:
        return None
    return json.loads(data.decode("utf-8"))


def write_message(message: dict, stream=None) -> None:
    stream = stream or sys.stdout.buffer
    encoded = json.dumps(message).encode("utf-8")
    stream.write(struct.pack("<I", len(encoded)))
    stream.write(encoded)
    stream.flush()


def handle(request: dict, store: CredentialStore, aliases: list | None = None) -> dict:
    cmd = request.get("cmd")
    if cmd == "ping":
        return {"ok": True, "count": len(store)}
    if cmd == "match":
        domain = request.get("domain", "")
        if not domain:
            return {"ok": False, "error": "missing domain"}
        matched = match_aliases(domain, aliases or [])
        return {"ok": True, "credentials": [c.wire_dict() for c in store.match(domain)],
                "aliases": [a.public_dict() for a in matched]}
    if cmd == "totp":
        domain, username = request.get("domain", ""), request.get("username", "")
        for c in store.match(domain):
            if c.username == username and c.totp:
                return {"ok": True, "totp": totp_codes.generate(c.totp)}
        return {"ok": False, "error": "no code for that login"}
    return {"ok": False, "error": f"unknown cmd {cmd!r}"}


def serve(store: CredentialStore, *, aliases: list | None = None,
         instream=None, outstream=None) -> None:
    """Blocking native-messaging loop. Returns when the extension disconnects (EOF)."""
    while True:
        request = read_message(instream)
        if request is None:
            return
        write_message(handle(request, store, aliases), outstream)


def _maybe_trigger_sync() -> None:
    """If the vault is older than ICP_SYNC_MAX_AGE (default 6h), kick off a detached `sync`
    in the background and return immediately - the current request is still served from the
    existing vault, and the refreshed data is picked up on the next host spawn.

    Best-effort: never blocks and never raises. A debounce marker stops a multi-frame page from
    launching many syncs at once; `sync` itself holds a lock so only one ever runs."""
    import os
    import subprocess
    import time

    from .. import paths
    try:
        max_age = int(os.environ.get("ICP_SYNC_MAX_AGE", str(6 * 3600)))
        if max_age <= 0:
            return  # auto-sync disabled
        vault = paths.vault_file()
        if vault.exists() and (time.time() - vault.stat().st_mtime) < max_age:
            return  # fresh enough
        attempt = paths.sync_attempt_file()
        if attempt.exists() and (time.time() - attempt.stat().st_mtime) < 300:
            return  # already triggered recently
        attempt.touch()
        subprocess.Popen(
            [sys.executable, "-m", "icp.cli.app", "sync"],
            stdin=subprocess.DEVNULL, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            start_new_session=True,
        )
    except Exception:
        pass


def main(argv=None) -> int:
    """Serve the decrypted vault; fall back to an empty store so the extension can still
    connect/ping when no vault has been synced yet. Hide My Email aliases are a best-effort
    add-on (empty list if no cache exists yet - the host never touches the network itself,
    the cache is only ever populated by `icp show`/`icp sync`)."""
    _maybe_trigger_sync()
    try:
        from .store import load_vault
        store = load_vault()
    except Exception:
        store = CredentialStore([])
    try:
        from ..hme.store import load_aliases
        aliases = load_aliases()
    except Exception:
        aliases = []
    serve(store, aliases=aliases)
    return 0


if __name__ == "__main__":
    sys.exit(main())

